mapper.select:
SELECT COALESCE(SUM(quantity), 0)
FROM sc_supply_chain_order
WHERE order_type = #{orderType}
  AND project_id = #{projectId}
  AND buyer_user_id = #{buyerUserId}
  AND platform_sku_id = #{platformSkuId}
  AND order_status NOT IN (#{failedStatus}, #{cancelledStatus})
  AND aftersale_status != #{fullyRefundedStatus}

  AND created_at >= #{startInclusive}


  AND created_at < #{endExclusive}

SELECT COALESCE(SUM(quantity), 0)
FROM sc_supply_chain_order
WHERE order_type = #{orderType}
  AND project_id = #{projectId}
  AND fulfillment_account_value = #{fulfillmentAccountValue}
  AND platform_sku_id = #{platformSkuId}
  AND order_status NOT IN (#{failedStatus}, #{cancelledStatus})
  AND aftersale_status != #{fullyRefundedStatus}

  AND created_at >= #{startInclusive}


  AND created_at < #{endExclusive}
